"""
Script to reproduce the config object creation issue.
"""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '.'))

from docker.models.configs import Config

def test_config_repr_issue():
    """Reproduce the KeyError when creating a config object and calling repr()."""
    print("Testing config object creation and repr...")

    # Create a config object with minimal attrs (simulating what might come from API)
    # This simulates the case where attrs doesn't have the expected 'Spec' -> 'Name' structure
    attrs_without_spec = {
        'ID': 'test_config_id',
        # Missing 'Spec' key entirely
    }

    try:
        config = Config(attrs=attrs_without_spec)
        print(f"Created config object: {config}")
        print("SUCCESS: No error occurred")
        return True
    except KeyError as e:
        print(f"ERROR: KeyError occurred when accessing name: {e}")
        return False
    except Exception as e:
        print(f"ERROR: Unexpected error: {e}")
        return False

def test_config_with_empty_spec():
    """Test config with Spec but without Name."""
    print("\nTesting config object with empty Spec...")

    attrs_with_empty_spec = {
        'ID': 'test_config_id',
        'Spec': {
            # Missing 'Name' key
        }
    }

    try:
        config = Config(attrs=attrs_with_empty_spec)
        print(f"Created config object: {config}")
        print("SUCCESS: No error occurred")
        return True
    except KeyError as e:
        print(f"ERROR: KeyError occurred when accessing name: {e}")
        return False
    except Exception as e:
        print(f"ERROR: Unexpected error: {e}")
        return False

def test_config_with_proper_structure():
    """Test config with proper Spec->Name structure."""
    print("\nTesting config object with proper structure...")

    attrs_with_proper_structure = {
        'ID': 'test_config_id',
        'Spec': {
            'Name': 'test_config_name'
        }
    }

    try:
        config = Config(attrs=attrs_with_proper_structure)
        print(f"Created config object: {config}")
        print("SUCCESS: No error occurred")
        return True
    except Exception as e:
        print(f"ERROR: Unexpected error: {e}")
        return False

if __name__ == "__main__":
    print("=" * 50)
    print("REPRODUCING CONFIG OBJECT ISSUE")
    print("=" * 50)

    success1 = test_config_repr_issue()
    success2 = test_config_with_empty_spec() 
    success3 = test_config_with_proper_structure()

    print("\n" + "=" * 50)
    print("SUMMARY:")
    print(f"Test 1 (no Spec): {'PASS' if success1 else 'FAIL'}")
    print(f"Test 2 (empty Spec): {'PASS' if success2 else 'FAIL'}")
    print(f"Test 3 (proper structure): {'PASS' if success3 else 'FAIL'}")

    if not (success1 and success2):
        print("\nThe issue is reproduced - KeyError occurs when Spec or Name is missing")
        sys.exit(1)
    else:
        print("\nNo issues found")
        sys.exit(0)"}

