"""

import re

from streamlink.plugin import Plugin, pluginmatcher
from streamlink.plugin.api import validate
from streamlink.stream.hls import HLSStream
from streamlink.utils.parse import parse_json


@pluginmatcher(re.compile(
    r"https?://www\.rtvs\.sk/televizia/live-[\w-]+",
))
class Rtvs(Plugin):
    # Channel ID mappings for non-numeric channel names
    _CHANNEL_MAP = {
        "o": "1",
        "rtvs": "2",
    }

    def _get_streams(self):
        # Extract channel ID from URL
        # Handle both numeric (live-1, live-24) and non-numeric (live-o, live-rtvs) formats
        match_numeric = re.search(r"/live-(\d+)$", self.url)
        match_named = re.search(r"/live-([a-zA-Z]+)$", self.url)

        channel_id = None
        if match_numeric:
            channel_id = match_numeric.group(1)
        elif match_named:
            channel_name = match_named.group(1)
            channel_id = self._CHANNEL_MAP.get(channel_name)

        if not channel_id:
            return

        res = self.session.http.get(
            "https://www.rtvs.sk/json/live5f.json",
            params={
                "c": channel_id,
                "b": "mozilla",
